# -*- coding: utf-8 -*-
# N1 内容理解(中文) tambahan · 3問 / 各
P1 = "Pahami argumen utama penulis: biasanya di kalimat penutup atau setelah しかし/とはいえ/むしろ."
P2 = "Soal alasan/指示語: baca kalimat sebelum dan sesudah bagian bergaris bawah; jawaban hampir selalu di sana."
P3 = "Pilihan yang memutlakkan (すべて・必ず・全く) atau memuat hal di luar teks hampir pasti salah."
JN = 'Teks menengah (内容理解・中文)'
R = ['Tidak disebut dalam teks.', 'Berlawanan dengan isi teks.', 'Berlebihan / bukan argumen penulis.']
def C(jp, id, qs):
    return dict(slot='chu', jenis=JN, jp=jp, id=id, qs=[(q, [ok] + w, 0, al, bu, R, [P2, P3, P1][i % 3]) for i, (q, ok, w, al, bu) in enumerate(qs)])
B = [
 C('「聞く」という行為は、一見、受け身で簡単なものに思える。しかし、相手の話を本当に聞くことは、実は高度な技術と忍耐を要する。\n　多くの人は、相手が話している間も、頭の中で自分の返答を準備している。これでは、相手の言葉は表面的にしか届かず、真意を取り逃してしまう。相手の言葉の背後にある感情や、言い淀んだ部分に注意を向けて初めて、その人が本当に伝えたいことが見えてくる。\n　とりわけ、意見が対立している場面では、相手の主張を遮らずに最後まで聞くことが難しい。だが、まず相手の考えを理解しようとする姿勢を示すことが、対立を解く第一歩となる。聞くとは、自分の考えを一時的に脇に置く、積極的な行為なのである。',
   'Tindakan "mendengar" sekilas tampak pasif dan mudah. Namun mendengar sungguh-sungguh pembicaraan lawan sebenarnya menuntut teknik tinggi dan kesabaran.\n Banyak orang, saat lawan berbicara pun, menyiapkan jawaban di kepalanya. Dengan begitu, kata lawan hanya sampai di permukaan dan maksud sebenarnya terlewat. Baru bila memperhatikan perasaan di balik kata dan bagian yang ragu-ragu diucapkan, tampak hal yang benar-benar ingin disampaikan orang itu.\n Terutama dalam situasi pendapat bertentangan, sulit mendengarkan hingga akhir tanpa menyela. Namun menunjukkan sikap berusaha memahami pikiran lawan lebih dulu adalah langkah pertama menyelesaikan pertentangan. Mendengar adalah tindakan aktif menyingkirkan sejenak pikiran sendiri.',
   [('筆者は、多くの 人が 話を 聞いて いる とき どう して いると 述べて いるか。', '頭の 中で 自分の 返答を 準備して いる', ['相手の 言葉を すべて 記憶して いる', '相手の 感情に 注意を 向けて いる', '何も 考えずに 聞いて いる'], 'Kebiasaan orang banyak.', '頭の中で自分の返答を準備している'),
    ('「真意を 取り逃して しまう」と 筆者が 述べる 理由は 何か。', '言葉が 表面的にしか 届かない から', ['相手が 本心を 隠して いる から', '話が 長すぎる から', '返答が 早すぎる から'], 'Alasan: hanya sampai permukaan.', '相手の言葉は表面的にしか届かず'),
    ('筆者は 「聞く」ことを どのような 行為と 考えて いるか。', '自分の 考えを 一時的に 脇に 置く 積極的な 行為', ['何も しない 受け身の 行為', '相手を 説得する 行為', '自分の 意見を 通す ための 行為'], 'Definisi di akhir.', '自分の考えを一時的に脇に置く、積極的な行為')]),
 C('日本には、「恥の文化」があると言われる。他人の目を意識し、世間から非難されることを避けるために行動を律するという特徴を指す。\n　この文化は、秩序を保ち、他者への配慮を促すという面では大きな役割を果たしてきた。しかし、一方で、失敗や弱さを見せることを過度に恐れ、助けを求めにくくなるという弊害も生んでいる。悩みを抱えながらも、周囲に打ち明けられずに一人で苦しむ人が少なくないのは、その表れだろう。\n　大切なのは、恥の意識を否定することではなく、「恥じるべきことは何か」を見直すことである。困っているときに助けを求めることは、本来恥ずべきことではない。むしろ、互いに弱さを見せ合える関係こそが、成熟した社会の証ではないだろうか。',
   'Dikatakan Jepang punya "budaya malu". Ini merujuk ciri mengendalikan perilaku demi menghindari celaan masyarakat karena sadar pandangan orang lain.\n Budaya ini berperan besar dalam menjaga ketertiban dan mendorong kepedulian pada orang lain. Namun di sisi lain, ia juga menimbulkan dampak buruk, yaitu takut berlebihan menunjukkan kegagalan dan kelemahan sehingga sulit meminta tolong. Banyaknya orang yang menyimpan masalah dan menderita sendiri karena tak bisa berterus terang pada sekitar adalah wujudnya.\n Yang penting bukan menyangkal rasa malu, melainkan meninjau ulang "apa yang patut dimalukan". Meminta tolong saat kesusahan pada dasarnya bukan hal memalukan. Bukankah hubungan yang bisa saling menunjukkan kelemahan justru bukti masyarakat dewasa?',
   [('「恥の 文化」の 利点と して 筆者が 認めて いる ことは 何か。', '秩序を 保ち、他者への 配慮を 促す こと', ['助けを 求めやすく なる こと', '失敗を 恐れなく なる こと', '世間の 目を 気に しなく なる こと'], 'Manfaat budaya malu.', '秩序を保ち、他者への配慮を促す'),
    ('「その 表れ」が 指す 内容は 何か。', '悩みを 一人で 抱え込んで しまう 人が 少なくない こと', ['助けを 求める 人が 増えて いる こと', '他人の 目を 気に しない 人が 増えた こと', '世間が 非難する こと'], 'Rujukan: orang menderita sendiri.', '助けを求めにくくなるという弊害…一人で苦しむ人が少なくない'),
    ('筆者の 考えに 最も 近い ものは どれか。', '助けを 求める ことは 恥では なく、弱さを 見せ合える 関係が 成熟した 社会の 証だ', ['恥の 意識は すべて なくす べきだ', '弱さは 隠す べきだ', '助けを 求める ことは 恥ずべきだ'], 'Kesimpulan akhir.', '互いに弱さを見せ合える関係こそが、成熟した社会の証')]),
 C('近年、都市部の若者を中心に、「サブスクリプション」型のサービスが広く利用されている。音楽や映像だけでなく、衣服や家具までもが、定額で「借りる」対象となった。\n　所有に伴う手間や費用を避けられる点は、確かに魅力的である。ものを持たない身軽さは、変化の激しい時代に適した生き方とも言える。\n　しかし、「所有しない」ことには代償もある。契約をやめれば、それまでに払った対価は何も残らない。また、気に入ったものを手元に置いて愛着を深めるという、ものとの関わり方も失われかねない。\n　便利さの陰で、私たちが何を手放しているのかを、時折立ち止まって考える必要があるだろう。',
   'Belakangan, terutama di kalangan anak muda kota, layanan tipe "langganan" dipakai luas. Bukan hanya musik dan video, bahkan pakaian dan perabot menjadi objek "disewa" dengan tarif tetap.\n Memang menarik karena bisa menghindari repot dan biaya yang menyertai kepemilikan. Keringanan tak memiliki barang bisa dibilang cara hidup yang cocok di era perubahan cepat.\n Namun "tak memiliki" ada harganya. Bila berhenti kontrak, tak ada yang tersisa dari bayaran sejauh ini. Juga cara berhubungan dengan barang, yakni menaruh yang disukai di tangan dan memperdalam keterikatan, bisa hilang.\n Di balik kepraktisan, perlu sesekali berhenti dan memikirkan apa yang kita lepaskan.',
   [('サブスクリプションの 利点と して 述べられて いる ことは 何か。', '所有に 伴う 手間や 費用を 避けられる こと', ['ものが 永久に 手元に 残る こと', '契約を やめても 対価が 戻る こと', '愛着が 深まる こと'], 'Manfaat langganan.', '所有に伴う手間や費用を避けられる'),
    ('筆者が 挙げて いる 「代償」に 当たらない ものは どれか。', '月額の 料金が 上がり 続ける こと', ['契約を やめると 何も 残らない こと', 'ものへの 愛着を 深めにくい こと', 'ものとの 関わり方が 失われる 恐れ'], 'Kenaikan tarif tidak disebut.', '対価は何も残らない…愛着を深める…関わり方も失われかねない'),
    ('筆者の 主張は どれか。', '便利さの 陰で 何を 手放して いるかを 考える べきだ', ['サブスクリプションは 利用すべきでは ない', '所有する ことが 最も 良い', '借りる ものを 増やす べきだ'], 'Kalimat akhir.', '何を手放しているのかを…考える必要がある')]),
 C('漢字の読み書きは、パソコンやスマートフォンの普及によって、苦手になったと感じる人が増えている。変換機能に頼れば、読めさえすれば書けなくても文章は作れるからだ。\n　確かに、手書きの機会が減るのは時代の流れであり、嘆いても仕方がない面はある。しかし、手で書くという行為には、単なる記録を超えた働きがある。一画一画をたどりながら書く過程で、文字の成り立ちや意味が自然と頭に刻まれるからだ。実際、手書きでノートを取った学生のほうが、キーボードで入力した学生よりも内容をよく理解していたという研究もある。\n　もちろん、すべてを手書きに戻す必要はない。だが、考えを深めたいときや、大切なことを記憶したいときには、あえて手で書くという選択肢を残しておきたい。',
   'Banyak orang merasa membaca-menulis kanji jadi lemah karena meluasnya komputer dan ponsel. Karena dengan fitur konversi, asal bisa membaca, kalimat bisa dibuat meski tak bisa menulis.\n Memang berkurangnya kesempatan menulis tangan arus zaman dan ada sisi yang tak berguna disesali. Namun menulis dengan tangan punya fungsi melampaui sekadar mencatat. Sebab dalam proses menulis goresan demi goresan, asal-usul dan makna huruf tertanam alami di kepala. Bahkan ada penelitian bahwa mahasiswa yang mencatat tulisan tangan lebih memahami isi daripada yang mengetik.\n Tentu tak perlu kembali menulis tangan untuk semuanya. Namun saat ingin memperdalam pikiran atau mengingat hal penting, saya ingin tetap menyisakan pilihan menulis tangan dengan sengaja.',
   [('漢字が 苦手に なった と 感じる 人が 増えた 理由は 何か。', '変換機能に 頼れば 書けなくても 文章が 作れる から', ['漢字が 難しく なった から', '手書きの 機会が 増えた から', '学校で 教えなく なった から'], 'Alasan: fitur konversi.', '変換機能に頼れば…書けなくても文章は作れる'),
    ('手書きの 利点と して 述べられて いる ことは 何か。', '文字の 成り立ちや 意味が 自然に 頭に 刻まれる こと', ['速く 書ける こと', '誤字が なくなる こと', '字が 上手に なる こと'], 'Manfaat tulisan tangan.', '文字の成り立ちや意味が自然と頭に刻まれる'),
    ('筆者の 考えに 合う ものは どれか。', '考えを 深めたい とき などに、手書きの 選択肢を 残したい', ['すべて 手書きに 戻す べきだ', '手書きは 時代遅れで 不要だ', '漢字は 書けなくても 良い'], 'Kalimat akhir.', 'あえて手で書くという選択肢を残しておきたい')]),
 C('ある町で、古い商店街の再開発をめぐって、住民の意見が二つに分かれた。再開発に賛成する人々は、老朽化した建物を建て替えれば、安全性が高まり、新しい店も入って町が活気づくと主張する。一方、反対する人々は、長年続いた店や、そこで育まれた人付き合いが失われることを懸念している。\n　どちらの主張にも一理ある。重要なのは、どちらが正しいかを決めつけることではなく、双方の懸念に耳を傾け、両立できる道を探ることだろう。例えば、古い建物の一部を残しながら、安全性を高める改修を行うという方法もありうる。\n　地域の問題は、多数決で片付けるのではなく、時間をかけて合意を形成していくことが、後の禍根を残さないために欠かせない。',
   'Di suatu kota, pendapat warga terbelah soal pembangunan ulang arkade toko tua. Pihak yang setuju berpendapat bila bangunan lapuk dibangun ulang, keamanan naik dan toko baru masuk sehingga kota bergairah. Pihak yang menentang mengkhawatirkan hilangnya toko yang bertahan bertahun-tahun dan hubungan antarorang yang terbina di sana.\n Kedua pendapat ada benarnya. Yang penting bukan memutuskan mana yang benar, melainkan mendengarkan kekhawatiran kedua pihak dan mencari jalan yang bisa selaras. Misalnya ada cara merenovasi untuk meningkatkan keamanan sambil menyisakan sebagian bangunan lama.\n Masalah daerah tak boleh diselesaikan dengan suara terbanyak; membentuk kesepakatan dengan waktu tak terpisahkan agar tak meninggalkan dendam.',
   [('再開発に 反対する 人々が 懸念して いる ことは 何か。', '長年 続いた 店や 人付き合いが 失われる こと', ['建物の 安全性が 下がる こと', '新しい 店が 入る こと', '町が 活気づく こと'], 'Kekhawatiran penentang.', '長年続いた店や…人付き合いが失われる'),
    ('筆者が 「重要」と 述べて いる ことは 何か。', '双方の 懸念に 耳を 傾け、両立できる 道を 探る こと', ['賛成派の 意見を 優先する こと', '反対派を 説得する こと', 'どちらが 正しいか 決める こと'], 'Hal penting.', '双方の懸念に耳を傾け、両立できる道を探る'),
    ('筆者は 地域の 問題の 解決に ついて どう 考えて いるか。', '多数決では なく、時間を かけて 合意を 作る べきだ', ['多数決で 素早く 決める べきだ', '行政が 一方的に 決める べきだ', '住民は 関わらない 方が 良い'], 'Kalimat akhir.', '多数決で片付けるのではなく、時間をかけて合意を形成')]),
 C('日本の「おもてなし」は、見返りを求めずに相手を思いやる心として、海外からも高く評価されている。客が言い出す前にその必要を察して応えることが、その真髄だとされる。\n　しかし、この心配りが、いつの間にか「当然受けるべきサービス」と受け取られ、過剰な要求につながっている面も否定できない。接客に携わる人々が、理不尽な要求に耐えることを強いられる例は、決して珍しくない。\n　本来のおもてなしは、提供する側と受ける側の間に、互いへの敬意があって成り立つものである。客もまた、心遣いに感謝し、相手を一人の人間として尊重することが求められる。おもてなしとは、一方的に与えられるものではなく、双方が育てていくものなのである。',
   '"Omotenashi" Jepang dinilai tinggi bahkan dari luar negeri sebagai hati yang memedulikan lawan tanpa meminta balasan. Esensinya disebut memahami dan menanggapi kebutuhan tamu sebelum diutarakan.\n Namun tak bisa dipungkiri kepedulian ini tanpa sadar diterima sebagai "layanan yang wajar diterima" dan berujung tuntutan berlebihan. Contoh orang yang bertugas melayani dipaksa menahan tuntutan tak masuk akal bukanlah hal langka.\n Omotenashi sejati terwujud bila ada rasa hormat timbal balik antara pemberi dan penerima. Tamu juga dituntut berterima kasih atas kepedulian dan menghormati lawan sebagai manusia. Omotenashi bukan sesuatu yang diberikan sepihak, melainkan sesuatu yang dibina oleh kedua pihak.',
   [('おもてなしの 真髄と して 述べられて いる ことは 何か。', '客が 言い出す 前に 必要を 察して 応える こと', ['客に 見返りを 求める こと', '客の 要求を すべて 断る こと', '料金を 高く 取る こと'], 'Esensi omotenashi.', '客が言い出す前にその必要を察して応える'),
    ('筆者が 問題だと 考えて いる ことは 何か。', 'サービスが 当然と 受け取られ、過剰な 要求に つながって いる こと', ['海外から 評価されない こと', '接客の 人が 少ない こと', '客が 感謝しすぎる こと'], 'Masalah.', '当然受けるべきサービス…過剰な要求につながっている'),
    ('筆者の 考える 本来の おもてなしとは どのような ものか。', '双方の 敬意に よって 成り立ち、双方が 育てる もの', ['提供する 側が 一方的に 与える もの', '料金に 見合う サービス', '客が 要求する もの'], 'Kalimat akhir.', '双方が育てていくもの')]),
 C('働き方改革が進み、長時間労働の是正が叫ばれている。確かに、過労による健康被害を防ぐことは何より重要である。\n　しかし、労働時間を短くするだけでは、問題は解決しない。仕事量が変わらないまま時間だけが減れば、限られた時間に仕事が集中し、かえって負担が増す恐れがある。また、仕事にやりがいを感じ、自ら進んで長く働きたいと考える人の意欲を、一律の規制が損なってしまう場合もある。\n　必要なのは、時間の長短だけに注目するのではなく、仕事の内容や進め方そのものを見直し、一人一人が納得して働ける環境を整えることである。働く時間をどう使うかという「質」の議論を欠いた改革は、形だけのものに終わりかねない。',
   'Reformasi cara kerja berjalan dan koreksi jam kerja panjang digaungkan. Memang mencegah kerugian kesehatan akibat kerja berlebihan sangat penting.\n Namun hanya mempersingkat jam kerja tak menyelesaikan masalah. Bila beban kerja tak berubah dan hanya waktu berkurang, pekerjaan terkonsentrasi di waktu terbatas dan beban justru bisa naik. Aturan seragam juga kadang merusak semangat orang yang merasa pekerjaannya bermakna dan ingin bekerja lama atas kemauan sendiri.\n Yang diperlukan adalah meninjau isi dan cara menjalankan pekerjaan sendiri, bukan hanya fokus panjang-pendek waktu, dan menata lingkungan di mana tiap orang bisa bekerja dengan rela. Reformasi tanpa diskusi "kualitas" cara memakai waktu kerja bisa berakhir sekadar bentuk.',
   [('筆者が 「長時間労働の 是正」に ついて 認めて いる ことは 何か。', '過労による 健康被害を 防ぐ ことは 重要だ', ['労働時間は 長い ほど 良い', '健康被害は 問題ない', '改革は 不要だ'], 'Pengakuan penulis.', '過労による健康被害を防ぐことは何より重要'),
    ('労働時間を 短く する だけで 起こりうる 問題と して 述べられて いる ことは 何か。', '限られた 時間に 仕事が 集中して かえって 負担が 増す こと', ['仕事が なくなる こと', '給料が 必ず 上がる こと', '休日が 増える こと'], 'Masalah memangkas jam saja.', '限られた時間に仕事が集中し、かえって負担が増す'),
    ('筆者が 必要だと 述べて いる ことは 何か。', '仕事の 内容や 進め方を 見直し、納得して 働ける 環境を 整える こと', ['労働時間を さらに 短くする こと', '規制を 廃止する こと', '長く 働く 人を 評価する こと'], 'Hal yang diperlukan.', '仕事の内容や進め方そのものを見直し')]),
 C('言葉の意味は、辞書に書かれた定義だけで決まるものではない。同じ「大丈夫」という言葉も、「問題ない」という意味にも、「結構です」と断る意味にもなる。どちらの意味で使われているかは、声の調子や表情、前後の文脈から判断するほかない。\n　この曖昧さは、コミュニケーションの弱点であると同時に、豊かさの源でもある。もし、すべての言葉が一つの意味しか持たなければ、詩や冗談のように、言外の意味を楽しむ表現は成立しない。\n　大切なのは、言葉の曖昧さを排除しようとすることではなく、相手の言葉が何を意味しているのかを、状況に即して丁寧に汲み取る姿勢である。誤解を恐れて確認することは、むしろ誠実なコミュニケーションの一部といえる。',
   'Makna kata tidak ditentukan hanya oleh definisi di kamus. Kata "daijoubu" yang sama bisa berarti "tak apa-apa" maupun menolak dengan "tak usah". Mana yang dimaksud tak ada pilihan selain menilai dari nada suara, ekspresi, dan konteks sekitarnya.\n Ambiguitas ini kelemahan komunikasi sekaligus sumber kekayaannya. Bila semua kata hanya punya satu makna, ungkapan seperti puisi dan lelucon yang menikmati makna tersirat tak akan terwujud.\n Yang penting bukan berusaha menyingkirkan ambiguitas, tetapi sikap memahami dengan teliti apa yang dimaksud kata lawan sesuai situasi. Memastikan karena takut salah paham justru bagian dari komunikasi yang tulus.',
   [('「大丈夫」の 例で 筆者が 示して いる ことは 何か。', '同じ 言葉でも 場面に よって 意味が 変わる こと', ['「大丈夫」は 一つの 意味しか ない こと', '辞書の 定義が 常に 正しい こと', '「大丈夫」は 失礼な 言葉である こと'], 'Contoh daijoubu.', '「問題ない」…「結構です」と断る意味'),
    ('曖昧さに ついて、筆者は どう 述べて いるか。', 'コミュニケーションの 弱点で あり、豊かさの 源でも ある', ['完全に 取り除く べきだ', '弱点でしか ない', '言葉に 曖昧さは ない'], 'Dua sisi ambiguitas.', '弱点であると同時に、豊かさの源'),
    ('筆者が 大切だと 考えて いる ことは 何か。', '状況に 即して 相手の 言葉を 丁寧に 汲み取る 姿勢', ['曖昧な 言葉を 使わない こと', '確認を 一切 しない こと', '辞書だけを 信じる こと'], 'Kalimat akhir.', '状況に即して丁寧に汲み取る姿勢')]),
]
